2-b9f0-254deb64a31f","label":"문제 2","order":1}]},{"sourceKey":"source:06ce30c195c160b5c8bd2bdcff13b2bc7e675fc09b12d6746f01e18985a9e05c","examId":"75e1851b-5f4d-582a-86c3-f9452482ab8f","existingExam":false,"universityId":"15f50d54-001d-49b9-836b-a5d9c76b9c0a","year":2025,"kind":"admission","track":"자연계열(수학)","session":null,"campus":"세종","examKey":"source-06ce30c195c160b5c8bd2bdcff13b2bc7e675fc09b12d6746f01e18985a9e05c","name":"홍익대학교 · 2025 · admission · 자연계열(수학) · 세종","sourceHashes":["88b9b0113d3679e5a38d06ef00983ba3dd5651226dcbd6414fc60dcc79bcdfa3"],"questions":[{"sourceKey":"source:06ce30c195c160b5c8bd2bdcff13b2bc7e675fc09b12d6746f01e18985a9e05c:1","id":"6bd88251-5c42-5794-b348-5f3acf0228e3","label":"문제 1","order":0},{"sourceKey":"source:06ce30c195c160b5c8bd2bdcff13b2bc7e675fc09b12d6746f01e18985a9e05c:2","id":"8abd5bd3-75f3-50a4-b5a5-b3621856b70b","label":"문제 2","order":1},{"sourceKey":"source:06ce30c195c160b5c8bd2bdcff13b2bc7e675fc09b12d6746f01e18985a9e05c:3","id":"9571e926-6281-54dc-94c2-e9975db07b31","label":"문제 3","order":2},{"sourceKey":"source:06ce30c195c160b5c8bd2bdcff13b2bc7e675fc09b12d6746f01e18985a9e05c:4","id":"ef21454c-4f1e-57f9-9393-8f03935e2917","label":"문제 4","order":3},{"sourceKey":"source:06ce30c195c160b5c8bd2bdcff13b2bc7e675fc09b12d6746f01e18985a9e05c:5","id":"0522cf7f-2a6b-5755-bdad-fbc005f7bcb4","label":"문제 5","order":4},{"sourceKey":"source:06ce30c195c160b5c8bd2bdcff13b2bc7e675fc09b12d6746f01e18985a9e05c:6","id":"29d84301-840b-5084-9913-b698151c558c","label":"문제 6","order":5},{"sourceKey":"source:06ce30c195c160b5c8bd2bdcff13b2bc7e675fc09b12d6746f01e18985a9e05c:7","id":"b136cc16-1640-5a46-a504-45668efa4429","label":"문제 7","order":6}]}]$registration$::jsonb) loop
  for q in select value from jsonb_array_elements(e->'questions') loop
   expected=jsonb_build_object('id',q->>'id','essay_exam_id',e->>'examId','question_key',q->>'sourceKey','label',q->>'label','display_order',(q->>'order')::int,'metadata_version','source-registration-v1','is_published',false);
   select jsonb_strip_nulls(to_jsonb(x)-'created_at') into actual from public.essay_questions x where id=(q->>'id')::uuid;
   if found and actual is distinct from expected then raise exception 'QUESTION_STATE_CHANGED';end if;
   if exists(select 1 from public.essay_practice_sessions where question_id=(q->>'id')::uuid) then raise exception 'LEARNING_RECORDS_EXIST';end if;
   delete from public.essay_questions where id=(q->>'id')::uuid;
  end loop;
  if not (e->>'existingExam')::boolean then
   expected=jsonb_strip_nulls(jsonb_build_object('id',e->>'examId','university_id',e->>'universityId','admission_year',(e->>'year')::int,'exam_key',e->>'examKey','exam_name',e->>'name','exam_kind',e->>'kind','campus',e->>'campus','field_or_division',e->>'track','session_label',e->>'session','verification_status','review','is_active',false));
   select jsonb_strip_nulls(to_jsonb(x)-array['created_at','updated_at']) into actual from public.essay_exams x where id=(e->>'examId')::uuid;
   if found and actual is distinct from expected then raise exception 'EXAM_STATE_CHANGED';end if;
   delete from public.essay_exams where id=(e->>'examId')::uuid;
  end if;
 end loop;
end $body$;
